from starlette.applications import Starlette
from starlette.responses import JSONResponse, PlainTextResponse
from starlette.routing import Route

from app import notes, views
from app.settings import DEBUG, SEED

STATS = {"started": 0, "stopped": 0}


def load_seed():
    notes.reset()
    for title in SEED:
        notes.add(title)
    STATS["started"] += 1


def close_store():
    STATS["stopped"] += 1


routes = [
    Route("/", views.homepage),
    Route("/notes", views.list_notes, methods=["GET"]),
    Route("/notes", views.create_note, methods=["POST"]),
    Route("/notes/latest", views.latest),
    Route("/notes/{note_id:int}", views.get_note, name="note"),
    Route("/health", views.health),
]

app = Starlette(debug=DEBUG, routes=routes, on_startup=[load_seed], on_shutdown=[close_store])


@app.middleware("http")
async def add_app_header(request, call_next):
    response = await call_next(request)
    response.headers["x-app"] = "notes"
    return response


@app.exception_handler(404)
async def not_found(request, exc):
    return JSONResponse({"error": exc.detail}, status_code=404)


@app.route("/version", methods=["GET"])
async def version(request):
    return PlainTextResponse("notes 1.0")

